const MAX_BODY_BYTES = 64 * 1024;
const MAX_CHAT_MESSAGES = 150;

export interface HearMeOutWebServerOptions {
  spmtOrigin: string;
  databasePath: string;
  port?: number;
  host?: string;
  buildSha?: string;
  personaConversation?: HearMeOutPersonaConversationCoordinator;
  credential?: string;
  operationMode?: SpmtOperationModeV1;
  suiteMediaResolver?: HearMeOutSuiteMediaResolverV1;
  voiceBridgeWorker?: HearMeOutVoiceBridgeWorkerV1;
  fetchImpl?: typeof fetch;
}

type RoomChatMessage = { id:string; tenantId:string; roomId:string; userId:string; displayName:string; text:string; createdAt:string; kind:"human"|"persona"|"system" };
type RoomPersona = { personaId:string; targetTenantId:string; displayName:string; wakeNames:string[]; joinedByUserId:string; joinedAt:string; transportHealthy:boolean };
type RoomMember = { userId:string; displayName:string; joinedAt:string };

class HearMeOutRoomConsoleStore {
  private readonly db:DatabaseSync;
  constructor(path:string){
    this.db=new DatabaseSync(path,{timeout:5_000});
    this.db.exec("PRAGMA journal_mode=WAL; PRAGMA synchronous=FULL; PRAGMA foreign_keys=ON;");
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS hmo_room_chat(
        tenant_id TEXT NOT NULL, room_id TEXT NOT NULL, message_id TEXT NOT NULL, created_at TEXT NOT NULL, body TEXT NOT NULL,
        PRIMARY KEY(tenant_id,room_id,message_id)
      ) STRICT;
      CREATE INDEX IF NOT EXISTS hmo_room_chat_order ON hmo_room_chat(tenant_id,room_id,created_at);
      CREATE TABLE IF NOT EXISTS hmo_room_personas(
        tenant_id TEXT NOT NULL, room_id TEXT NOT NULL, persona_id TEXT NOT NULL, body TEXT NOT NULL,
        PRIMARY KEY(tenant_id,room_id,persona_id)
      ) STRICT;
    `);
  }
  close(){this.db.close();}
  listChat(tenantId:string,roomId:string,limit=MAX_CHAT_MESSAGES):RoomChatMessage[]{return (this.db.prepare("SELECT body FROM hmo_room_chat WHERE tenant_id=? AND room_id=? ORDER BY created_at DESC LIMIT ?").all(tenantId,roomId,limit) as Array<{body:string}>).reverse().map(row=>JSON.parse(row.body) as RoomChatMessage);}
  appendChat(principal:HearMeOutPrincipalV1,roomId:string,text:string,kind:RoomChatMessage["kind"]="human",displayName=principal.displayName):RoomChatMessage{const message:RoomChatMessage={id:`msg-${Date.now().toString(36)}-${randomBytes(5).toString("hex")}`,tenantId:principal.tenantId,roomId,userId:principal.userId,displayName:cleanLabel(displayName,"displayName",120),text:cleanMessage(text),createdAt:new Date().toISOString(),kind};this.db.prepare("INSERT INTO hmo_room_chat(tenant_id,room_id,message_id,created_at,body) VALUES(?,?,?,?,?)").run(message.tenantId,message.roomId,message.id,message.createdAt,JSON.stringify(message));return message;}
  appendPersona(tenantId:string,roomId:string,personaId:string,displayName:string,text:string):RoomChatMessage{const message:RoomChatMessage={id:`msg-${Date.now().toString(36)}-${randomBytes(5).toString("hex")}`,tenantId,roomId,userId:`persona:${personaId}`,displayName:cleanLabel(displayName,"displayName",120),text:cleanMessage(text),createdAt:new Date().toISOString(),kind:"persona"};this.db.prepare("INSERT INTO hmo_room_chat(tenant_id,room_id,message_id,created_at,body) VALUES(?,?,?,?,?)").run(message.tenantId,message.roomId,message.id,message.createdAt,JSON.stringify(message));return message;}
  listPersonas(tenantId:string,roomId:string):RoomPersona[]{return (this.db.prepare("SELECT body FROM hmo_room_personas WHERE tenant_id=? AND room_id=? ORDER BY persona_id").all(tenantId,roomId) as Array<{body:string}>).map(row=>JSON.parse(row.body) as RoomPersona);}
  putPersona(principal:HearMeOutPrincipalV1,roomId:string,persona:{personaId:string;targetTenantId?:string;displayName:string;wakeNames?:string[];transportHealthy?:boolean}):RoomPersona{const value:RoomPersona={personaId:cleanId(persona.personaId,"personaId"),targetTenantId:cleanId(persona.targetTenantId??persona.personaId,"targetTenantId"),displayName:cleanLabel(persona.displayName,"displayName",120),wakeNames:[...new Set((persona.wakeNames??[]).map(value=>cleanLabel(value,"wakeName",96)))].slice(0,50),joinedByUserId:principal.userId,joinedAt:new Date().toISOString(),transportHealthy:persona.transportHealthy===true};this.db.prepare("INSERT INTO hmo_room_personas(tenant_id,room_id,persona_id,body) VALUES(?,?,?,?) ON CONFLICT(tenant_id,room_id,persona_id) DO UPDATE SET body=excluded.body").run(principal.tenantId,roomId,value.personaId,JSON.stringify(value));return value;}
  removePersona(tenantId:string,roomId:string,personaId:string){this.db.prepare("DELETE FROM hmo_room_personas WHERE tenant_id=? AND room_id=? AND persona_id=?").run(tenantId,roomId,cleanId(personaId,"personaId"));return{removed:true as const};}
  deleteRoom(tenantId:string,roomId:string){this.db.prepare("DELETE FROM hmo_room_chat WHERE tenant_id=? AND room_id=?").run(tenantId,roomId);this.db.prepare("DELETE FROM hmo_room_personas WHERE tenant_id=? AND room_id=?").run(tenantId,roomId);}
}

export function createHearMeOutWebServer(options:HearMeOutWebServerOptions){
  const spmtOrigin=loopbackOrigin(options.spmtOrigin),databasePath=resolve(options.databasePath),rooms=new SqliteHearMeOutRoomMediaRuntime(databasePath),consoleStore=new HearMeOutRoomConsoleStore(databasePath),voiceStore=options.voiceBridgeWorker?new SqliteHearMeOutVoiceBridgeStore(databasePath):undefined,voiceBridge=voiceStore&&options.voiceBridgeWorker?new HearMeOutVoiceBridgeController(rooms,voiceStore,options.voiceBridgeWorker):undefined,suiteController=new AbortController();
  let suiteFailure="",suiteTask:Promise<void>|undefined;
  if(options.credential){const getAccessToken=createHearMeOutWorkerTokenProvider({spmtOrigin,credential:options.credential,...(options.fetchImpl?{fetchImpl:options.fetchImpl}:{})}),client=new SpmtClient({baseUrl:spmtOrigin,appId:"hearmeout",getAccessToken,...(options.fetchImpl?{fetchImpl:options.fetchImpl}:{})}),media=options.suiteMediaResolver??new SpmtHearMeOutSuiteMediaResolver(client),actions=HEARMEOUT_BOT_ACTIONS.filter(action=>!action.startsWith("hmo.bot.")||options.operationMode==="read-only"||Boolean(options.personaConversation)).filter(action=>!action.startsWith("hmo.voice.")||options.operationMode==="read-only"||Boolean(voiceBridge)),executor=new HearMeOutWebSuiteActionExecutor(rooms,media,{...(options.personaConversation?{personaConversation:options.personaConversation,personaStore:consoleStore}:{}),...(voiceBridge?{voiceBridge}:{})}),worker=new HearMeOutSuiteActionWorker(client,executor,{workerId:`hearmeout-web-suite-${process.pid}`,actions});suiteTask=worker.run(suiteController.signal).catch(error=>{suiteFailure=safeError(error)});}
  const server=createServer(async(request,response)=>{try{const url=new URL(request.url??"/","http://hearmeout.green");if(request.method==="GET"&&(url.pathname==="/"||url.pathname==="/apps/hearmeout")){applyPageHeaders(response);return send(response,200,renderHearMeOutWebPage(options.buildSha??"dev"),"text/html; charset=utf-8");}if(request.method==="GET"&&url.pathname==="/health/ready")return sendJson(response,suiteFailure?503:200,{state:suiteFailure?"degraded":"ready",appId:"hearmeout",...(suiteFailure?{suiteActions:suiteFailure}:{})});if(url.pathname.startsWith("/api/hearmeout/"))return await handleApi(request,response,url,rooms,consoleStore,spmtOrigin,options.personaConversation);return sendJson(response,404,{error:"not_found",message:"Unknown HearMeOut route"});}catch(error){if(!response.headersSent)return sendJson(response,500,{error:"hearmeout_web_failure",message:safeError(error)});response.destroy(error instanceof Error?error:undefined);}});
  return{server,async listen(){await listen(server,options.port??3200,options.host??"127.0.0.1");},async close(){suiteController.abort();await suiteTask;voiceStore?.close();consoleStore.close();rooms.close();if(server.listening)await close(server);}};
}

export async function startHearMeOutWebServerFromEnvironment(environment:NodeJS.ProcessEnv=process.env){const spmtOrigin=environment.SPMT_ORIGIN??"",databasePath=environment.HEARMEOUT_ROOM_DATABASE_PATH??"",operationMode:SpmtOperationModeV1=environment.SPMT_OUTBOUND_MODE==="disabled"?"read-only":"active";if(!databasePath)throw new Error("HEARMEOUT_ROOM_DATABASE_PATH is required");const bridgeOrigin=environment.HEARMEOUT_VOICE_BRIDGE_ORIGIN,bridgeAuthorization=environment.HEARMEOUT_VOICE_BRIDGE_AUTHORIZATION;if(Boolean(bridgeOrigin)!==Boolean(bridgeAuthorization))throw new Error("HearMeOut voice bridge origin and authorization must be configured together");const voiceBridgeWorker=operationMode==="active"&&bridgeOrigin&&bridgeAuthorization?new ResilientHearMeOutVoiceBridgeWorker(new HttpHearMeOutVoiceBridgeWorker({workerOrigin:bridgeOrigin,getAuthorization:()=>bridgeAuthorization})):undefined;const host=createHearMeOutWebServer({spmtOrigin,databasePath,operationMode,port:Number(environment.PORT??3200),host:environment.HOST??"127.0.0.1",buildSha:environment.BUILD_SHA??"dev",...(environment.HEARMEOUT_WORKER_CREDENTIAL?{credential:environment.HEARMEOUT_WORKER_CREDENTIAL}:{}),...(voiceBridgeWorker?{voiceBridgeWorker}: {})});await host.listen();return host;}

async function handleApi(request:IncomingMessage,response:ServerResponse,url:URL,rooms:SqliteHearMeOutRoomMediaRuntime,consoleStore:HearMeOutRoomConsoleStore,spmtOrigin:string,personaConversation?:HearMeOutPersonaConversationCoordinator){
  try{
    const principal=await resolvePrincipal(request,spmtOrigin);
    if(request.method==="GET"&&url.pathname==="/api/hearmeout/rooms")return sendJson(response,200,{rooms:rooms.listRooms(principal).map(room=>roomSummary(rooms,principal,room))});
    if(request.method==="POST"&&url.pathname==="/api/hearmeout/rooms"){requireSameOrigin(request);const body=await readJson(request),name=requiredText(body.name,"name",120),privacy=body.privacy==="private"?"private":"public",password=privacy==="private"&&typeof body.password==="string"&&body.password?body.password:undefined;const room=rooms.createRoom(principal,{roomId:makeRoomId(name),name,privacy,...(password?{password}:{}),operationId:`web-create:${principal.userId}:${randomBytes(8).toString("hex")}`});return sendJson(response,201,room);}
    if(request.method==="GET"&&url.pathname==="/api/hearmeout/assistant")return sendJson(response,200,await spmtJson(request,spmtOrigin,principal.tenantId,"/v1/assistants/community"));
    const detail=url.pathname.match(/^\/api\/hearmeout\/rooms\/([^/]+)$/);
    if(detail){
      const roomId=decodeURIComponent(detail[1]!);
      if(request.method==="DELETE"){requireSameOrigin(request);const result=rooms.deleteRoom(principal,roomId,`web-delete:${principal.userId}:${randomBytes(8).toString("hex")}`);consoleStore.deleteRoom(principal.tenantId,roomId);return sendJson(response,200,result);}
      if(request.method==="GET"){const room=rooms.getRoom(principal.tenantId,roomId);if(!room)return sendJson(response,404,{error:"room_not_found",message:"HearMeOut room not found or expired"});return sendJson(response,200,roomDetail(rooms,consoleStore,principal,room));}
    }
    const join=url.pathname.match(/^\/api\/hearmeout\/rooms\/([^/]+)\/join$/);
    if(request.method==="POST"&&join){requireSameOrigin(request);const body=await readJson(request);return sendJson(response,200,rooms.joinRoom(principal,decodeURIComponent(join[1]!),`web-join:${principal.userId}:${randomBytes(8).toString("hex")}`,undefined,typeof body.password==="string"&&body.password?{password:body.password}:{}));}
    const leave=url.pathname.match(/^\/api\/hearmeout\/rooms\/([^/]+)\/leave$/);
    if(request.method==="POST"&&leave){requireSameOrigin(request);return sendJson(response,200,rooms.leaveRoom(principal,decodeURIComponent(leave[1]!),`web-leave:${principal.userId}:${randomBytes(8).toString("hex")}`));}
    const moderation=url.pathname.match(/^\/api\/hearmeout\/rooms\/([^/]+)\/moderation$/);
    if(request.method==="POST"&&moderation){requireSameOrigin(request);const body=await readJson(request),action=String(body.action??"");if(action!=="kick"&&action!=="timeout"&&action!=="ban")throw new Error("HearMeOut moderation action is invalid");return sendJson(response,200,rooms.moderateMember(principal,{roomId:decodeURIComponent(moderation[1]!),targetUserId:requiredText(body.targetUserId,"targetUserId",160),action,durationSeconds:body.durationSeconds===undefined?undefined:Number(body.durationSeconds),operationId:`web-moderate:${principal.userId}:${randomBytes(8).toString("hex")}`}));}
    const presence=url.pathname.match(/^\/api\/hearmeout\/rooms\/([^/]+)\/presence$/);
    if(request.method==="POST"&&presence){requireSameOrigin(request);const body=await readJson(request);return sendJson(response,200,rooms.heartbeatPresence(principal,decodeURIComponent(presence[1]!),requiredText(body.connectionId,"connectionId",200)));}
    const chat=url.pathname.match(/^\/api\/hearmeout\/rooms\/([^/]+)\/chat$/);
    if(chat){const roomId=decodeURIComponent(chat[1]!);requireMembership(rooms,principal,roomId);if(request.method==="GET")return sendJson(response,200,{messages:consoleStore.listChat(principal.tenantId,roomId),surface:"commlink"});if(request.method==="POST"){requireSameOrigin(request);const body=await readJson(request);return sendJson(response,201,{message:consoleStore.appendChat(principal,roomId,requiredText(body.text,"text",2000)),surface:"legacy-room-chat"});}}
    const media=url.pathname.match(/^\/api\/hearmeout\/rooms\/([^/]+)\/media\/(movie|music)$/);
    if(request.method==="POST"&&media){requireSameOrigin(request);const roomId=decodeURIComponent(media[1]!),lane=media[2] as HearMeOutMediaLaneV1;requireMembership(rooms,principal,roomId);const body=await readJson(request),title=requiredText(body.title,"title",300),playbackUrl=playableUrl(body.playbackUrl),durationSeconds=optionalDuration(body.durationSeconds),itemId=`${lane}-${Date.now().toString(36)}-${randomBytes(5).toString("hex")}`;const session=rooms.enqueue(principal,{roomId,lane,item:{itemId,type:lane==="movie"?"movie":"music",title,source:"user-url",playbackUrl,...(durationSeconds===undefined?{}:{durationSeconds})},operationId:`web-enqueue:${principal.userId}:${randomBytes(8).toString("hex")}`});return sendJson(response,201,session);}
    const control=url.pathname.match(/^\/api\/hearmeout\/rooms\/([^/]+)\/media\/(movie|music)\/control$/);
    if(request.method==="POST"&&control){requireSameOrigin(request);const body=await readJson(request),action=String(body.action??"");if(!["play","pause","seek","mute","unmute","volume","next","jump","clear"].includes(action))throw new Error("HearMeOut media action is invalid");const session=rooms.control(principal,{roomId:decodeURIComponent(control[1]!),lane:control[2] as HearMeOutMediaLaneV1,action:action as any,operationId:`web-control:${principal.userId}:${randomBytes(8).toString("hex")}`,...(typeof body.position==="number"?{position:body.position}:{}),...(typeof body.targetIndex==="number"?{targetIndex:body.targetIndex}:{}),...(typeof body.expectedRequestId==="string"?{expectedRequestId:body.expectedRequestId}:{})});return sendJson(response,200,session);}
    const personas=url.pathname.match(/^\/api\/hearmeout\/rooms\/([^/]+)\/personas$/);
    if(personas){const roomId=decodeURIComponent(personas[1]!);requireMembership(rooms,principal,roomId);if(request.method==="GET"){const catalog=personaConversation?await personaConversation.gallery():[];return sendJson(response,200,{personas:consoleStore.listPersonas(principal.tenantId,roomId),catalog,...(!personaConversation?{assistant:await spmtJson(request,spmtOrigin,principal.tenantId,"/v1/assistants/community")}:{})});}if(request.method==="POST"){requireSameOrigin(request);const body=await readJson(request);if(personaConversation){const catalog=await personaConversation.gallery(),requested=typeof body.personaId==="string"?body.personaId:"",persona=catalog.find(item=>item.personaId===requested||item.targetTenantId===requested)??(catalog.length===1?catalog[0]:undefined);if(!persona)throw new Error("Select a public HearMeOut persona");const joined=await personaConversation.control({action:"join",roomId,persona});return sendJson(response,201,{persona:consoleStore.putPersona(principal,roomId,{...persona,transportHealthy:joined.worker.transportHealthy!==false}),worker:joined.worker});}const assistant=await spmtJson(request,spmtOrigin,principal.tenantId,"/v1/assistants/community") as Record<string,unknown>,personaId=requiredText(assistant.personaId??assistant.id??"community-assistant","personaId",200),displayName=requiredText(assistant.displayName??assistant.name??"Assistant","displayName",120);return sendJson(response,201,{persona:consoleStore.putPersona(principal,roomId,{personaId,displayName})});}}
    const personaTranscribe=url.pathname.match(/^\/api\/hearmeout\/rooms\/([^/]+)\/personas\/transcribe$/);
    if(request.method==="POST"&&personaTranscribe){requireSameOrigin(request);const roomId=decodeURIComponent(personaTranscribe[1]!);requireMembership(rooms,principal,roomId);if(!personaConversation)throw new Error("HearMeOut persona transcription is unavailable");const body=await readJson(request,17*1024*1024);return sendJson(response,200,await personaConversation.transcribe(String(body.base64Audio??"")));}
    const personaRemove=url.pathname.match(/^\/api\/hearmeout\/rooms\/([^/]+)\/personas\/([^/]+)$/);
    if(request.method==="DELETE"&&personaRemove){requireSameOrigin(request);const roomId=decodeURIComponent(personaRemove[1]!),personaId=decodeURIComponent(personaRemove[2]!);requireMembership(rooms,principal,roomId);const present=consoleStore.listPersonas(principal.tenantId,roomId).find(item=>item.personaId===personaId);if(present&&personaConversation){const catalog=await personaConversation.gallery(),persona=catalog.find(item=>item.personaId===present.personaId||item.targetTenantId===present.targetTenantId);if(persona)await personaConversation.control({action:"leave",roomId,persona});}return sendJson(response,200,consoleStore.removePersona(principal.tenantId,roomId,personaId));}
    const personaInvoke=url.pathname.match(/^\/api\/hearmeout\/rooms\/([^/]+)\/personas\/([^/]+)\/invoke$/);
    if(request.method==="POST"&&personaInvoke){requireSameOrigin(request);const roomId=decodeURIComponent(personaInvoke[1]!),personaId=decodeURIComponent(personaInvoke[2]!);requireMembership(rooms,principal,roomId);const persona=consoleStore.listPersonas(principal.tenantId,roomId).find(item=>item.personaId===personaId);if(!persona)throw new Error("Persona is not in this room");const body=await readJson(request),message=requiredText(body.message,"message",4000);consoleStore.appendChat(principal,roomId,message);if(personaConversation){const result=await personaConversation.command({roomId,targetTenantId:persona.targetTenantId||persona.personaId,command:message,actor:{userId:principal.userId,username:principal.displayName,displayName:principal.displayName},speak:body.speak!==false});consoleStore.appendPersona(principal.tenantId,roomId,persona.personaId,result.botName,result.reply);return sendJson(response,200,{...result,persona});}const accepted=await spmtJson(request,spmtOrigin,principal.tenantId,"/v1/assistants/community/invocations",{method:"POST",headers:{"content-type":"application/json","idempotency-key":`hmo-room-persona:${roomId}:${randomBytes(10).toString("hex")}`},body:JSON.stringify({userId:principal.userId,message,surface:"app",conversationId:`hearmeout:${roomId}`,routingPreference:"automatic",remember:true})});consoleStore.appendPersona(principal.tenantId,roomId,persona.personaId,persona.displayName,"I picked that up. My response job is now running in Stellar Core.");return sendJson(response,202,{accepted,persona});}
    return sendJson(response,404,{error:"not_found",message:"Unknown HearMeOut Green route"});
  }catch(error){const message=safeError(error),status=/session|sign in|unauthor/i.test(message)?401:/not found|expired/i.test(message)?404:/password|member|admin|owner|moderate|banned|timed out|denied/i.test(message)?403:400;return sendJson(response,status,{error:"hearmeout_green_request_failed",message});}
}

function roomSummary(runtime:SqliteHearMeOutRoomMediaRuntime,principal:HearMeOutPrincipalV1,room:HearMeOutRoomV1){
  const members=runtime.listMembers(principal.tenantId,room.roomId) as RoomMember[],member=members.some(item=>item.userId===principal.userId),canManage=room.ownerUserId===principal.userId||principal.roles.includes("admin"),presence=safePresence(runtime,principal.tenantId,room.roomId),activeIds=new Set(presence.map(item=>item.userId)),participantCount=activeIds.size;
  if(room.privacy==="private"&&!member&&!canManage)return{roomId:room.roomId,name:room.name,privacy:"private",locked:true,member:false,participantCount};
  const participants=members.filter(item=>activeIds.has(item.userId)).map(item=>({userId:item.userId,displayName:item.displayName,joinedAt:item.joinedAt}));
  if(room.privacy==="private")return{roomId:room.roomId,name:room.name,privacy:"private",locked:false,member,participantCount,canManage};
  return{roomId:room.roomId,name:room.name,privacy:"public",member,participantCount,createdAt:room.createdAt,participants,activity:publicActivity(runtime,principal.tenantId,room.roomId),canManage};
}
function roomDetail(runtime:SqliteHearMeOutRoomMediaRuntime,store:HearMeOutRoomConsoleStore,principal:HearMeOutPrincipalV1,room:HearMeOutRoomV1){
  const members=runtime.listMembers(principal.tenantId,room.roomId) as RoomMember[],member=members.some(item=>item.userId===principal.userId),canManage=room.ownerUserId===principal.userId||principal.roles.includes("admin"),presence=safePresence(runtime,principal.tenantId,room.roomId),activeIds=new Set(presence.map(item=>item.userId)),participantCount=activeIds.size,viewer={userId:principal.userId,displayName:principal.displayName,canManage,isOwner:room.ownerUserId===principal.userId};
  if(room.privacy==="private"&&!member&&!canManage)return{room:{roomId:room.roomId,name:room.name,privacy:"private"},member:false,locked:true,participantCount,viewer};
  if(!member&&room.privacy==="public"){const participants=members.filter(item=>activeIds.has(item.userId)).map(item=>({userId:item.userId,displayName:item.displayName,joinedAt:item.joinedAt}));return{room:{roomId:room.roomId,name:room.name,privacy:"public",createdAt:room.createdAt},member:false,lobby:true,participants,participantCount,activity:publicActivity(runtime,principal.tenantId,room.roomId),viewer};}
  return{room,member:true,viewer,members,presence,music:runtime.getSession(principal.tenantId,room.roomId,"music"),movie:runtime.getSession(principal.tenantId,room.roomId,"movie"),chat:store.listChat(principal.tenantId,room.roomId),personas:store.listPersonas(principal.tenantId,room.roomId)};
}
function safePresence(runtime:SqliteHearMeOutRoomMediaRuntime,tenantId:string,roomId:string){try{return runtime.listActivePresence(tenantId,roomId)}catch{return[]}}
function publicActivity(runtime:SqliteHearMeOutRoomMediaRuntime,tenantId:string,roomId:string){const movie=runtime.getSession(tenantId,roomId,"movie"),music=runtime.getSession(tenantId,roomId,"music");return{watchParty:Boolean(movie.current),musicBot:Boolean(music.current||music.queue.length),watchState:movie.current?movie.playback.status:"idle",musicState:music.current?music.playback.status:"idle"};}
function requireMembership(rooms:SqliteHearMeOutRoomMediaRuntime,principal:HearMeOutPrincipalV1,roomId:string){const members=rooms.listMembers(principal.tenantId,roomId);if(!members.some(item=>item.userId===principal.userId))throw new Error("HearMeOut room membership is required");}
async function spmtJson(request:IncomingMessage,origin:string,tenantId:string,path:string,init:RequestInit={}){const headers=new Headers(init.headers);headers.set("accept","application/json");headers.set("x-spmt-app","hearmeout");headers.set("x-spmt-tenant",tenantId);if(request.headers.cookie)headers.set("cookie",request.headers.cookie);const response=await fetch(`${origin}${path}`,{...init,headers,redirect:"manual"});const text=await response.text();let payload:unknown={};try{payload=text?JSON.parse(text):{};}catch{}if(!response.ok)throw new Error((payload&&typeof payload==="object"&&!Array.isArray(payload)&&typeof (payload as any).message==="string")?(payload as any).message:`SPMT request failed (${response.status})`);return payload;}

